servicios:
cat > /home/learner/aso/p32/servicios.sh <<'ASO_EOF'
#!/bin/bash
(($#!=1)) && { echo "uso: servicios.sh ESTADO" >&2; exit 1; }
case $1 in
  enabled|disabled|static) ;;
  *) echo "estado no válido" >&2; exit 2;;
esac
systemctl --root=/ list-unit-files --type=service --state="$1" --no-legend --no-pager | awk '{print $1}'
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p32/servicios.sh
chown learner:learner /home/learner/aso/p32/servicios.sh

demonios:
cat > /home/learner/aso/p32/demonios.sh <<'ASO_EOF'
#!/bin/bash
[[ $# -gt 1 || ( $# -eq 1 && $1 != -c ) ]] && { echo "uso: demonios.sh [-c]" >&2; exit 1; }
lista() {
  for fichero in /usr/lib/systemd/system/*.service; do
    nombre=${fichero##*/}
    [[ $nombre =~ d\.service$ ]] && echo "$nombre"
  done | LC_ALL=C sort
}
if [[ $1 == -c ]]; then lista | wc -l; else lista; fi
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p32/demonios.sh
chown learner:learner /home/learner/aso/p32/demonios.sh
